/bin/zsh -lc "python3 - <<'PY'
import json
from pathlib import Path
for fn in ['source.json','policy.json','coordination.json','result-schema.json']:
 p=Path(fn); d=json.loads(p.read_text()); print(fn, 'bytes',p.stat().st_size,'type',type(d).__name__)
 if isinstance(d,dict):
  for k,v in d.items():
   print(k, type(v).__name__,len(v) if hasattr(v,'__len__') else '',len(json.dumps(v,ensure_ascii=False)))
 else:
  for i,v in enumerate(d):
   print(i, {k:(len(x) if isinstance(x,(str,list,dict)) else x) for k,x in v.items()})
PY"

